/* ===== OpenLearnHub — Global Styles ===== */

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --navy: #0a0a23;
  --gold: #feac32;
  --link-blue: #002ead;
  --white: #ffffff;
  --off-white: #f5f6f7;
  --gray-100: #f0f0f0;
  --gray-200: #dfdfe2;
  --gray-300: #d0d0d5;
  --gray-500: #858591;
  --gray-700: #4a4a4f;
  --gray-900: #1b1b32;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --shadow-card: 0 1px 3px rgba(10,10,35,0.08), 0 1px 2px rgba(10,10,35,0.06);
  --shadow-hover: 0 4px 12px rgba(10,10,35,0.12);
  --transition: 0.2s ease;
  --max-width: 1200px;
}

html {
  font-size: 16px;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--link-blue);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

img {
  max-width: 100%;
  display: block;
}

/* ===== Header ===== */

.site-header {
  background: var(--navy);
  color: var(--white);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.25rem;
  display: flex;
  align-items: center;
  height: 60px;
  gap: 1rem;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--white);
  font-weight: 700;
  font-size: 1.125rem;
  text-decoration: none;
  flex-shrink: 0;
}

.logo:hover {
  text-decoration: none;
}

.logo-icon {
  width: 32px;
  height: 32px;
  background: var(--gold);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 1rem;
  color: var(--navy);
}

.search-bar {
  flex: 1;
  max-width: 480px;
  position: relative;
}

.search-bar input {
  width: 100%;
  padding: 0.5rem 0.75rem 0.5rem 2.25rem;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: var(--radius-sm);
  background: rgba(255,255,255,0.08);
  color: var(--white);
  font-size: 0.875rem;
  outline: none;
  transition: border-color var(--transition);
}

.search-bar input::placeholder {
  color: rgba(255,255,255,0.5);
}

.search-bar input:focus {
  border-color: var(--gold);
}

.search-bar svg {
  position: absolute;
  left: 0.625rem;
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  color: rgba(255,255,255,0.5);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  list-style: none;
}

.nav-links a {
  color: var(--white);
  font-size: 0.875rem;
  font-weight: 500;
  opacity: 0.85;
  transition: opacity var(--transition);
}

.nav-links a:hover {
  opacity: 1;
  text-decoration: none;
}

.hamburger {
  display: none;
  background: none;
  border: none;
  color: var(--white);
  cursor: pointer;
  padding: 0.25rem;
}

.hamburger svg {
  width: 24px;
  height: 24px;
}

.mobile-menu {
  display: none;
  background: var(--navy);
  border-top: 1px solid rgba(255,255,255,0.1);
}

.mobile-menu.open {
  display: block;
}

.mobile-menu a {
  display: block;
  color: var(--white);
  padding: 0.875rem 1.25rem;
  font-size: 0.9375rem;
  border-bottom: 1px solid rgba(255,255,255,0.05);
}

.mobile-menu a:hover {
  background: rgba(255,255,255,0.05);
  text-decoration: none;
}

/* ===== Banner ===== */

.banner {
  background: var(--gold);
  text-align: center;
  padding: 0.625rem 1rem;
}

.banner a {
  color: var(--navy);
  font-weight: 600;
  font-size: 0.9375rem;
}

.banner a:hover {
  text-decoration: underline;
}

/* ===== Main Content ===== */

.main {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 2rem 1.25rem 3rem;
}

/* ===== Article Grid ===== */

.section-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
  color: var(--gray-900);
}

.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.article-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: box-shadow var(--transition), transform var(--transition);
  cursor: pointer;
}

.article-card:hover {
  box-shadow: var(--shadow-hover);
  transform: translateY(-2px);
}

.card-thumb {
  width: 100%;
  aspect-ratio: 16/9;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-500);
  font-size: 2rem;
  position: relative;
}

.card-thumb svg {
  width: 48px;
  height: 48px;
  opacity: 0.3;
}

.card-body {
  padding: 1rem 1.125rem 1.125rem;
}

.card-tag {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  padding: 0.2em 0.6em;
  border-radius: var(--radius-sm);
  margin-bottom: 0.5rem;
}

.tag-ai { background: #e0e7ff; color: #3730a3; }
.tag-scraping { background: #fef3c7; color: #92400e; }
.tag-databases { background: #d1fae5; color: #065f46; }
.tag-elasticsearch { background: #ede9fe; color: #5b21b6; }
.tag-engineering { background: #fce7f3; color: #9d174d; }
.tag-automation { background: #e0f2fe; color: #0369a1; }
.tag-python { background: #fef9c3; color: #854d0e; }
.tag-nodejs { background: #dcfce7; color: #166534; }
.tag-sheets { background: #e0f2fe; color: #0c4a6e; }

.card-title {
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.4;
  color: var(--gray-900);
  margin-bottom: 0.75rem;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.card-meta {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.8125rem;
  color: var(--gray-500);
}

.avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--gray-700);
  flex-shrink: 0;
}

.card-meta .author {
  font-weight: 500;
  color: var(--gray-700);
}

.card-meta .sep {
  color: var(--gray-300);
}

/* ===== Load More ===== */

.load-more-wrap {
  text-align: center;
  margin-top: 2rem;
}

.btn-load-more {
  display: inline-block;
  background: var(--navy);
  color: var(--white);
  border: none;
  padding: 0.75rem 2rem;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background var(--transition);
}

.btn-load-more:hover {
  background: var(--gray-900);
}

/* ===== Featured Article ===== */

.featured {
  margin-bottom: 2.5rem;
}

.featured-card {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 2rem;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  overflow: hidden;
  cursor: pointer;
  transition: box-shadow var(--transition);
}

.featured-card:hover {
  box-shadow: var(--shadow-hover);
}

.featured-thumb {
  aspect-ratio: 16/10;
  background: linear-gradient(135deg, #1a1a4e 0%, #0a0a23 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.featured-thumb svg {
  width: 80px;
  height: 80px;
  opacity: 0.15;
  color: var(--white);
}

.featured-body {
  padding: 2rem 2rem 2rem 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.featured-body .card-tag {
  width: fit-content;
}

.featured-body .card-title {
  font-size: 1.375rem;
  -webkit-line-clamp: 4;
  margin-bottom: 1rem;
}

/* ===== Tag Page ===== */

.tag-header {
  margin-bottom: 1.5rem;
}

.tag-header h1 {
  font-size: 2rem;
  font-weight: 800;
  text-transform: uppercase;
  color: var(--gray-900);
}

.tag-header p {
  color: var(--gray-500);
  font-size: 0.9375rem;
  margin-top: 0.25rem;
}

.popular-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 2rem;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid var(--gray-200);
}

.popular-tag {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.375rem 0.75rem;
  background: var(--off-white);
  border: 1px solid var(--gray-200);
  border-radius: 999px;
  font-size: 0.8125rem;
  color: var(--gray-700);
  white-space: nowrap;
  transition: background var(--transition);
}

.popular-tag:hover {
  background: var(--gray-200);
  text-decoration: none;
}

.popular-tag .count {
  font-size: 0.75rem;
  color: var(--gray-500);
}

/* ===== Learn Page ===== */

.learn-welcome {
  background: var(--off-white);
  border-radius: var(--radius-lg);
  padding: 2rem;
  margin-bottom: 2.5rem;
  text-align: center;
}

.learn-welcome h1 {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}

.learn-welcome p {
  color: var(--gray-700);
  font-size: 1rem;
}

.learn-welcome .btn-signin {
  display: inline-block;
  margin-top: 1rem;
  background: var(--gold);
  color: var(--navy);
  font-weight: 600;
  padding: 0.625rem 1.5rem;
  border-radius: var(--radius-md);
  transition: opacity var(--transition);
}

.learn-welcome .btn-signin:hover {
  opacity: 0.9;
  text-decoration: none;
}

.learn-section {
  margin-bottom: 2.5rem;
}

.learn-section h2 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 1rem;
  padding-bottom: 0.5rem;
  border-bottom: 2px solid var(--gold);
  display: inline-block;
}

.cert-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.cert-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.875rem 1rem;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  transition: box-shadow var(--transition), border-color var(--transition);
  cursor: pointer;
}

.cert-item:hover {
  box-shadow: var(--shadow-card);
  border-color: var(--gold);
}

.cert-icon {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background: var(--off-white);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 1.1rem;
}

.cert-name {
  font-weight: 500;
  font-size: 0.9375rem;
  color: var(--gray-900);
}

.challenge-box {
  background: linear-gradient(135deg, var(--navy) 0%, #1b1b32 100%);
  color: var(--white);
  border-radius: var(--radius-lg);
  padding: 2rem;
  text-align: center;
  margin-bottom: 2.5rem;
}

.challenge-box h2 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 1rem;
  border: none;
  padding: 0;
}

.challenge-links {
  display: flex;
  justify-content: center;
  gap: 1rem;
  flex-wrap: wrap;
}

.challenge-links a {
  color: var(--gold);
  font-weight: 600;
  font-size: 0.9375rem;
}

.challenge-links a:hover {
  color: var(--white);
}

.prep-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 0.75rem;
}

.prep-item {
  padding: 0.75rem 1rem;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  color: var(--gray-900);
  transition: border-color var(--transition);
  cursor: pointer;
}

.prep-item:hover {
  border-color: var(--gold);
  text-decoration: none;
}

/* ===== Donate Page ===== */

.donate-hero {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 2.5rem;
  padding: 2.5rem 1rem 0;
}

.donate-hero h1 {
  font-size: 2.25rem;
  font-weight: 800;
  color: var(--navy);
  margin-bottom: 1rem;
}

.donate-hero p {
  font-size: 1.0625rem;
  line-height: 1.7;
  color: var(--gray-700);
}

.donate-form {
  max-width: 500px;
  margin: 0 auto 3rem;
  text-align: center;
}

.amount-tabs {
  display: flex;
  gap: 0.5rem;
  justify-content: center;
  margin-bottom: 1.25rem;
}

.amount-tab {
  padding: 0.75rem 1.5rem;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-md);
  background: var(--white);
  font-size: 1.0625rem;
  font-weight: 700;
  color: var(--gray-700);
  cursor: pointer;
  transition: all var(--transition);
  min-width: 72px;
}

.amount-tab:hover {
  border-color: var(--gold);
}

.amount-tab.active {
  background: var(--gold);
  border-color: var(--gold);
  color: var(--navy);
}

.donate-desc {
  font-size: 0.9375rem;
  color: var(--gray-700);
  margin-bottom: 1.25rem;
  min-height: 2.5rem;
}

.btn-donate {
  display: inline-block;
  background: var(--gold);
  color: var(--navy);
  font-size: 1.125rem;
  font-weight: 700;
  padding: 0.875rem 3rem;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: opacity var(--transition);
}

.btn-donate:hover {
  opacity: 0.9;
}

.donate-sub {
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-top: 0.75rem;
}

.donate-sub a {
  color: var(--link-blue);
}

/* Benefits / Initiatives / Achievements */

.donate-section {
  max-width: 720px;
  margin: 0 auto 2.5rem;
}

.donate-section h2 {
  font-size: 1.375rem;
  font-weight: 700;
  margin-bottom: 1rem;
  color: var(--navy);
}

.donate-section ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.donate-section li {
  padding: 0.75rem 1rem;
  background: var(--off-white);
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  color: var(--gray-700);
  display: flex;
  align-items: flex-start;
  gap: 0.625rem;
}

.donate-section li::before {
  content: "";
  flex-shrink: 0;
  width: 6px;
  height: 6px;
  margin-top: 0.5rem;
  background: var(--gold);
  border-radius: 50%;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1rem;
}

.stat-card {
  background: var(--off-white);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  text-align: center;
}

.stat-number {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--navy);
  margin-bottom: 0.25rem;
}

.stat-label {
  font-size: 0.8125rem;
  color: var(--gray-500);
}

/* ===== FAQ Accordion ===== */

.faq-section {
  max-width: 720px;
  margin: 0 auto 3rem;
}

.faq-section h2 {
  font-size: 1.375rem;
  font-weight: 700;
  margin-bottom: 1rem;
  color: var(--navy);
}

.faq-item {
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  margin-bottom: 0.5rem;
  overflow: hidden;
}

.faq-question {
  width: 100%;
  text-align: left;
  padding: 1rem 1.25rem;
  background: var(--white);
  border: none;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--gray-900);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  transition: background var(--transition);
}

.faq-question:hover {
  background: var(--off-white);
}

.faq-chevron {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform 0.3s ease;
  color: var(--gray-500);
}

.faq-item.open .faq-chevron {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}

.faq-item.open .faq-answer {
  max-height: 300px;
}

.faq-answer-inner {
  padding: 0 1.25rem 1rem;
  font-size: 0.875rem;
  line-height: 1.7;
  color: var(--gray-700);
}

/* ===== Footer ===== */

.site-footer {
  background: var(--navy);
  color: rgba(255,255,255,0.7);
  padding: 3rem 1.25rem;
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-mission {
  font-size: 0.875rem;
  line-height: 1.7;
  max-width: 680px;
  margin-bottom: 2rem;
}

.footer-section {
  margin-bottom: 1.5rem;
}

.footer-section h3 {
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--gold);
  margin-bottom: 0.75rem;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem 1rem;
}

.footer-links a {
  color: rgba(255,255,255,0.6);
  font-size: 0.8125rem;
  transition: color var(--transition);
}

.footer-links a:hover {
  color: var(--white);
  text-decoration: none;
}

.footer-bottom {
  margin-top: 2rem;
  padding-top: 1.5rem;
  border-top: 1px solid rgba(255,255,255,0.1);
  font-size: 0.75rem;
  color: rgba(255,255,255,0.4);
}

/* ===== Responsive ===== */

@media (max-width: 900px) {
  .article-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .featured-card {
    grid-template-columns: 1fr;
  }

  .featured-body {
    padding: 1.5rem;
  }
}

@media (max-width: 640px) {
  .article-grid {
    grid-template-columns: 1fr;
  }

  .nav-links {
    display: none;
  }

  .search-bar {
    display: none;
  }

  .hamburger {
    display: block;
    margin-left: auto;
  }

  .header-inner {
    height: 52px;
  }

  .featured-body .card-title {
    font-size: 1.125rem;
  }

  .donate-hero h1 {
    font-size: 1.75rem;
  }

  .amount-tabs {
    flex-wrap: wrap;
  }

  .tag-header h1 {
    font-size: 1.5rem;
  }

  .learn-welcome h1 {
    font-size: 1.375rem;
  }

  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}
